begin;
create extension if not exists pgtap with schema extensions;
select plan(25);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values
('00000000-0000-0000-0000-000000000000','92600000-0000-4000-8000-000000000001','authenticated','authenticated','interview-owner@example.test','',now(),now(),now()),
('00000000-0000-0000-8000-000000000000','92600000-0000-4000-8000-000000000002','authenticated','authenticated','interview-outsider@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','92600000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"92600000-0000-4000-8000-000000000001","role":"authenticated"}',true);select public.create_business('interview-test','Interview Test','Interview Test','sole_proprietorship','retail','{"city":"Manila"}');select set_config('test.interview_org',(select id::text from public.organizations where slug='interview-test'),true);
select is(public.can_business_permission(current_setting('test.interview_org')::uuid,'ai.manage'),true,'Owner can run the business interview');
select set_config('test.interview_id',(select public.start_ai_business_interview(current_setting('test.interview_org')::uuid,'Tell me about your business.')::text),true);
select ok(current_setting('test.interview_id')::uuid is not null,'Interview starts with a tenant-scoped id');
select is((select content from public.ai_business_interview_messages where interview_id=current_setting('test.interview_id')::uuid),'Tell me about your business.','Interview begins conversationally with an assistant message');
select throws_ok($$update public.ai_business_interviews set status='approved'where id=current_setting('test.interview_id')::uuid$$,'42501','permission denied for table ai_business_interviews','Clients cannot bypass interview lifecycle controls');
select throws_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'industry','Hardware store','{"industry":"retail_hardware"}','branches','Skipped a topic',null)$$,'22023','Invalid interview turn.','A turn cannot skip the progressive stage sequence');
select lives_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'industry','Hardware store','{"industry":"retail_hardware"}','size','How large is the team?',null)$$,'Industry answer advances the profile');
select lives_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'size','Small with twelve people','{"industry":"retail_hardware","businessSize":"small","employeeCount":12}','branches','How many branches?',null)$$,'Size answer advances the profile');
select lives_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'branches','Three branches','{"industry":"retail_hardware","businessSize":"small","employeeCount":12,"branchCount":3}','sales','How do sales happen?',null)$$,'Branch answer advances the profile');
select lives_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'sales','Counter and quotations','{"salesChannels":["in_store","quotations_invoices"]}','inventory','How is stock handled?',null)$$,'Sales answer advances the profile');
select lives_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'inventory','Manual per branch','{"inventoryHandling":"multi_branch_stock"}','customers','How do customers interact?',null)$$,'Inventory answer advances the profile');
select lives_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'customers','Walk-ins and Messenger','{"customerInteractions":["walk_in","messenger"]}','employees_workflows','How does the team work?',null)$$,'Customer answer advances the profile');
select lives_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'employees_workflows','Managers approve discounts','{"employeeWorkflows":"Managers approve discounts"}','operational_problems','What are the problems?',null)$$,'Workflow answer advances the profile');
select lives_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'operational_problems','Stock differences and collections','{"operationalProblems":["stock differences","collections"]}','current_tools','What tools are used?',null)$$,'Problems answer advances the profile');
select lives_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'current_tools','Paper Excel POS and Messenger','{"currentTools":["paper","excel","pos","messenger"]}','goals','What are the goals?',null)$$,'Tools answer advances the profile');
select lives_ok($$select public.record_ai_business_interview_turn(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'goals','Reduce losses and grow','{"goals":["reduce losses","grow"]}','complete','Recommendations are ready.','{"processSummary":"Summary","recommendedBusinessOS":{"templateKey":"retail-store-os"},"modules":[],"automations":[],"dashboards":[],"digitalReadiness":{"total":50}}')$$,'Final answer generates recommendation-only output');
select is((select status||':'||current_stage from public.ai_business_interviews where id=current_setting('test.interview_id')::uuid),'completed:complete','Completed interview waits for human review');
select is((select count(*)from public.ai_business_interview_messages where interview_id=current_setting('test.interview_id')::uuid),21::bigint,'All ten user turns and assistant responses are retained');
select ok((select recommendation is not null from public.ai_business_interviews where id=current_setting('test.interview_id')::uuid),'Structured recommendations are stored');
select is((select count(*)from public.configuration_change_sets where organization_id=current_setting('test.interview_org')::uuid),0::bigint,'Completing an interview creates no configuration proposal');
select is((select count(*)from public.organization_configuration_revisions where organization_id=current_setting('test.interview_org')::uuid),0::bigint,'Completing an interview does not change configuration revision');
select lives_ok($$select public.review_ai_business_interview(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'approved')$$,'User can approve recommendations');
select is((select status from public.ai_business_interviews where id=current_setting('test.interview_id')::uuid),'approved','Approval is recorded on the recommendation');
select is((select count(*)from public.configuration_change_sets where organization_id=current_setting('test.interview_org')::uuid),0::bigint,'Recommendation approval still applies no system changes');
select throws_ok($$select public.review_ai_business_interview(current_setting('test.interview_org')::uuid,current_setting('test.interview_id')::uuid,'approved')$$,'P0001','Recommendation is not awaiting review.','Recommendations cannot be reviewed twice');
select set_config('request.jwt.claim.sub','92600000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"92600000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.start_ai_business_interview(current_setting('test.interview_org')::uuid,'Cross-tenant interview')$$,'42501','Permission denied.','Outsiders cannot start interviews for another tenant');
select *from finish();rollback;
